    vals=[l['data'][k] for l in lines if k in l['data']]
    if all(isinstance(v,(int,float)) for v in vals):
        print(f'{k}: n={len(vals)} first={vals[0]:.4g} last={vals[-1]:.4g} min={min(vals):.4g} max={max(vals):.4g}')
    else:
        print(f'{k}: n={len(vals)} nonnumeric e.g. {vals[0]!r}')
